import config, daemon, tempfile
from pathlib import Path
root = Path(tempfile.mkdtemp())
def write(name, data):
    path = root / name
    path.write_bytes(data)
    return path
good = write('good.json', b'{"merge_enabled": false, "max_workers": 2}')
bad = write('bad.json', b'{"merge_enabled": false,}')
outcomes = []
for data in [b'[]', b'{"merge_enabled": false, "max_wrokers": 2}', b'{"max_workers": "8"}', b'{"max_workers": true}', b'\xff\xfe', b'']:
    try:
        outcomes.append(['returned', config.load_overrides(write('shape.json', data))])
    except config.ConfigError:
        outcomes.append('ConfigError')
    except Exception as exc:
        outcomes.append(type(exc).__name__)
state = {'config': dict(config.DEFAULTS), 'degraded': 'previous error'}
state = daemon.reload(state, write('fixed.json', b'{"region": "eu-west"}'))
result = [outcomes, config.load_overrides(root / 'absent.json'), state['config']['region'], state['degraded']]
